create extension if not exists pgcrypto;
create type public.user_role as enum ('customer','professional');
create table public.users (id uuid primary key references auth.users(id) on delete cascade,role public.user_role not null default 'customer',full_name text not null check(char_length(full_name) between 1 and 120),avatar_url text,phone text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.professional_profiles (id uuid primary key default gen_random_uuid(),user_id uuid not null unique references public.users(id) on delete cascade,business_name text not null check(char_length(business_name) between 1 and 120),bio text check(char_length(bio)<=1000),location text,is_verified boolean not null default false,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.interests (id uuid primary key default gen_random_uuid(),name text not null unique,slug text not null unique check(slug ~ '^[a-z0-9]+(?:-[a-z0-9]+)*$'),created_at timestamptz not null default now());
alter table public.users enable row level security; alter table public.professional_profiles enable row level security; alter table public.interests enable row level security;
create policy "users read own profile" on public.users for select to authenticated using ((select auth.uid())=id);
create policy "users insert own profile" on public.users for insert to authenticated with check ((select auth.uid())=id);
create policy "users update own profile" on public.users for update to authenticated using ((select auth.uid())=id) with check ((select auth.uid())=id);
create policy "professional profiles publicly readable" on public.professional_profiles for select to anon,authenticated using (true);
create policy "professionals insert own profile" on public.professional_profiles for insert to authenticated with check ((select auth.uid())=user_id and exists(select 1 from public.users u where u.id=(select auth.uid()) and u.role='professional'));
create policy "professionals update own profile" on public.professional_profiles for update to authenticated using ((select auth.uid())=user_id) with check ((select auth.uid())=user_id);
create policy "professionals delete own profile" on public.professional_profiles for delete to authenticated using ((select auth.uid())=user_id);
create policy "interests publicly readable" on public.interests for select to anon,authenticated using (true);
create or replace function public.set_updated_at() returns trigger language plpgsql security invoker set search_path='' as $$ begin new.updated_at=now(); return new; end; $$;
create trigger users_set_updated_at before update on public.users for each row execute function public.set_updated_at();
create trigger professional_profiles_set_updated_at before update on public.professional_profiles for each row execute function public.set_updated_at();
revoke all on public.users,public.professional_profiles,public.interests from anon,authenticated;
grant select,insert on public.users to authenticated; grant update(full_name,avatar_url,phone) on public.users to authenticated;
grant select on public.professional_profiles to anon,authenticated; grant insert,delete on public.professional_profiles to authenticated; grant update(business_name,bio,location) on public.professional_profiles to authenticated;
grant select on public.interests to anon,authenticated;
insert into public.interests(name,slug) values ('Hair','hair'),('Barbering','barbering'),('Nails','nails'),('Makeup','makeup'),('Skincare','skincare');
